func TestAmendLoadedOverflowRejected(t *testing.T) {
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", math.MaxInt64); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", math.MaxInt64-10, "X", true); err != nil {
		t.Fatal(err)
	}
