	if err := r.RegisterCargo("G1", 10, "Shanghai", true); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G2", 10, "Beijing", true); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Adjust("A0", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
