	}
	// G2 改成与 G1 相同目的地并关闭混装，最终合法即应成功。
	if err := r.AmendCargo("G2", 10, "Shanghai", false); err != nil {
		t.Fatalf("目的地改成一致后关闭混装应成功: %v", err)
	}
