	}
	if _, err := r.Adjust("A0", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
	}); err != nil {
		t.Fatal(err)
	}
	// G2 增重到 50（合计 110 超重）同时改新目的地并关闭混装（混装也冲突）。
	se := requireError(t, r.AmendCargo("G2", 50, "Guangzhou", false), ErrOverweight)
	if se.ID != "C1" {
