130	// 清单，正式提交必须按更正后的重量判断——C2 预计 110 千克超过承重
131	// 100 千克，整次调整拒绝，且不能返回成功调整结果。
132	func TestStalePreviewSubmitAfterAmendOverweightRejected(t *testing.T) {
133		r, ops, old := setupStalePreviewScenario(t)
134	
135		// 更正 G1 重量 20 -> 40；目的地与混装许可保持原值，G1 仍在 C1。
136		if err := r.AmendCargo("G1", 40, "X", false); err != nil {
