161		}
162	
163		// 拒绝后整次调整不生效，资料更正也不能被撤回。
164		g1, _ = r.Cargo("G1")
165		if g1.Weight != 40 || g1.Destination != "X" || g1.AllowMixed ||
166			!g1.Loaded || g1.CompartmentID != "C1" {
167			t.Fatalf("拒绝后 G1 应仍以 40 千克留在 C1（更正不撤回、移动不执行）: %+v", g1)
168		}
169		g2, _ := r.Cargo("G2")
170		if g2.Weight != 60 || !g2.Loaded || g2.CompartmentID != "C2" {
171			t.Fatalf("拒绝后 G2 应仍以 60 千克留在 C2: %+v", g2)
172		}
173		g3, _ := r.Cargo("G3")
