9	// loadAll 登记舱位与货物并按 ops 完成若干次正式调整的测试辅助。
10	func mustAdjust(t *testing.T, r *Registry, id string, ops []Op) *AdjustmentResult {
11		t.Helper()
12		res, err := r.Adjust(id, ops)
13		if err != nil {
14			t.Fatalf("调整 %s 意外失败: %v", id, err)
15		}
16		return res
17	}
