19	// cargoIDs 取出舱位快照中的货物编号清单。
20	func cargoIDs(v CompartmentView) []string {
21		ids := make([]string, 0, len(v.Cargo))
22		for _, c := range v.Cargo {
23			ids = append(ids, c.ID)
24		}
25		return ids
26	}
