30	func TestPreviewAfterListsShowProjectedPositions(t *testing.T) {
31		r := NewRegistry()
32		if err := r.RegisterCompartment("C1", 100); err != nil {
33			t.Fatal(err)
34		}
35		if err := r.RegisterCompartment("C2", 100); err != nil {
36			t.Fatal(err)
37		}
38		if err := r.RegisterCargo("G1", 10, "X", true); err != nil {
39			t.Fatal(err)
40		}
41		if err := r.RegisterCargo("G2", 20, "X", false); err != nil {
42			t.Fatal(err)
43		}
44		mustAdjust(t, r, "A1", []Op{{Kind: OpLoad, CargoID: "G2", Target: "C1"}})
45	
46		// 装未装载的 G1 到 C2，并把 G2 从 C1 移到 C2。
47		res, err := r.Preview([]Op{
48			{Kind: OpLoad, CargoID: "G1", Target: "C2"},
49			{Kind: OpMove, CargoID: "G2", Target: "C2"},
50		})
51		if err != nil {
52			t.Fatal(err)
53		}
54		if !res.Submittable {
55			t.Fatalf("应可提交: %+v", res.Rejections)
56		}
57		c1, c2 := res.Compartments[0], res.Compartments[1]
58	
59		// C1 的 Before 保留 G2 及其原位置；After 为空。
60		if len(c1.Before.Cargo) != 1 || c1.Before.Cargo[0].ID != "G2" ||
61			!c1.Before.Cargo[0].Loaded || c1.Before.Cargo[0].CompartmentID != "C1" {
62			t.Fatalf("C1 调整前清单应保留 G2 原位置: %+v", c1.Before.Cargo)
63		}
64		if len(c1.After.Cargo) != 0 {
65			t.Fatalf("C1 预计清单应为空: %+v", c1.After.Cargo)
66		}
67	
68		// C2 的 After 中两件货物都显示已装载且属于 C2，登记资料不变。
69		if len(c2.After.Cargo) != 2 {
70			t.Fatalf("C2 预计清单应含两件货物: %+v", c2.After.Cargo)
71		}
72		for _, cv := range c2.After.Cargo {
73			if !cv.Loaded || cv.CompartmentID != "C2" {
74				t.Fatalf("预计清单中的货物应显示已装载于 C2: %+v", cv)
75			}
76		}
77		g1, g2 := c2.After.Cargo[0], c2.After.Cargo[1]
78		if g1.ID != "G1" || g1.Weight != 10 || g1.Destination != "X" || !g1.AllowMixed {
79			t.Fatalf("G1 登记资料不应被改写: %+v", g1)
80		}
81		if g2.ID != "G2" || g2.Weight != 20 || g2.Destination != "X" || g2.AllowMixed {
82			t.Fatalf("G2 登记资料不应被改写: %+v", g2)
83		}
84	
85		// 预览后登记状态不变。
86		cv, _ := r.Cargo("G1")
87		if cv.Loaded || cv.CompartmentID != "" {
88			t.Fatalf("预览不应改变货物状态: %+v", cv)
89		}
90	}
