		t.Fatal(err)
	}
	mustAdjust(t, r, "A1", []Op{{Kind: OpLoad, CargoID: "G1", Target: "C1"}})

	check := func(name string, ops []Op, kind ErrorKind, id string) {
		t.Helper()
		res, err := r.Preview(ops)
		se := requireError(t, err, kind)
		if se.ID != id {
			t.Fatalf("%s：错误应指向 %q，实际 %q", name, id, se.ID)
