	check("货物不存在", []Op{{Kind: OpLoad, CargoID: "GX", Target: "C1"}}, ErrNotFound, "GX")
	check("舱位不存在", []Op{{Kind: OpLoad, CargoID: "G2", Target: "CX"}}, ErrNotFound, "CX")
