161				cpt, _ := r.Compartment("C1")
162				if cpt.UsedWeight != 40 || cpt.RemainingWeight != 60 || len(cpt.Cargo) != 1 {
163					t.Fatalf("C1 最终配载错误: %+v", cpt)
164				}
165				if cpt.Cargo[0].ID != "G3" || cpt.Cargo[0].AllowMixed {
166					t.Fatalf("C1 应只剩 G3 且保留其不允许混装登记: %+v", cpt.Cargo[0])
167				}
168				assertReplaceProfilesUnchanged(t, r, false)
169			})
170		}
171	}
172	
173	// 只卸下 G1、装入允许混装的 G3：最终留下去上海且不允许混装的 G2，
174	// 与去北京的 G3 共舱。总重量 70 未超重，仍必须按混装冲突拒绝整次调整，
175	// 且不能因卸货操作排在前面就把 G1 单独卸下。先卸后装与先装后卸结论一致。
176	func TestPartialReplaceMixedConflictRejected(t *testing.T) {
177		for _, tc := range []struct {
