186				},
187			},
188			{
189				name: "先装后卸",
190				ops: []Op{
191					{Kind: OpLoad, CargoID: "G3", Target: "C1"},
192					{Kind: OpUnload, CargoID: "G1"},
193				},
194			},
195		} {
196			t.Run(tc.name, func(t *testing.T) {
197				r := newReplaceRegistry(t, true)
198				res, err := r.Adjust("A1", tc.ops)
199				if err == nil {
200					t.Fatalf("留有不允许混装的 G2 时应拒绝整次调整，却返回成功: %+v", res)
201				}
202				if res != nil {
203					t.Fatalf("被拒绝的调整不应返回成功结果: %+v", res)
204				}
