package stowage

import (
	"strings"
	"testing"
)

// newReplaceRegistry 构造同舱更换目的地货物的初始配载：
// C1 承重 100；G1（20，上海，不允许混装）、G2（30，上海，不允许混装）
// 已装入 C1；G3（40，北京，混装许可由参数指定）尚未装载。
func newReplaceRegistry(t *testing.T, g3AllowMixed bool) *Registry {
	t.Helper()
	r := NewRegistry()
	if err := r.RegisterCompartment("C1", 100); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G1", 20, "Shanghai", false); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G2", 30, "Shanghai", false); err != nil {
		t.Fatal(err)
	}
	if err := r.RegisterCargo("G3", 40, "Beijing", g3AllowMixed); err != nil {
		t.Fatal(err)
	}
	if _, err := r.Adjust("A0", []Op{
		{Kind: OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: OpLoad, CargoID: "G2", Target: "C1"},
	}); err != nil {
		t.Fatal(err)
	}
	return r
}

// assertReplaceProfilesUnchanged 核对三件货物登记的重量、目的地与混装许可
// 始终不变，仅归属随调整结果改变。
func assertReplaceProfilesUnchanged(t *testing.T, r *Registry, g3AllowMixed bool) {
	t.Helper()
	g1, _ := r.Cargo("G1")
	if g1.Weight != 20 || g1.Destination != "Shanghai" || g1.AllowMixed {
		t.Fatalf("G1 登记资料被改变: %+v", g1)
	}
	g2, _ := r.Cargo("G2")
	if g2.Weight != 30 || g2.Destination != "Shanghai" || g2.AllowMixed {
		t.Fatalf("G2 登记资料被改变: %+v", g2)
	}
	g3, _ := r.Cargo("G3")
	if g3.Weight != 40 || g3.Destination != "Beijing" || g3.AllowMixed != g3AllowMixed {
		t.Fatalf("G3 登记资料被改变: %+v", g3)
	}
}

// 同一次调整中卸下原目的地的 G1、G2 并装入新目的地的 G3：合法性以全部
// 操作完成后的最终配载判断，原货物尚未移出的临时共舱不算混装冲突。
// 装入写在卸货之前或之后，结论与最终查询结果都应一致。
func TestReplaceDestinationCargoSuccess(t *testing.T) {
	for _, tc := range []struct {
		name string
		ops  []Op
	}{
		{
			name: "先卸后装",
			ops: []Op{
				{Kind: OpUnload, CargoID: "G1"},
				{Kind: OpUnload, CargoID: "G2"},
				{Kind: OpLoad, CargoID: "G3", Target: "C1"},
			},
		},
		{
			name: "先装后卸",
			ops: []Op{
				{Kind: OpLoad, CargoID: "G3", Target: "C1"},
				{Kind: OpUnload, CargoID: "G1"},
				{Kind: OpUnload, CargoID: "G2"},
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := newReplaceRegistry(t, true)
			res, err := r.Adjust("A1", tc.ops)
			if err != nil {
				t.Fatalf("原货物全部移出后只剩 G3，应成功: %v", err)
			}
			// 成功结果保留此次调整编号。
			if res.ID != "A1" {
				t.Fatalf("结果编号错误: %+v", res)
			}
			// 两件卸下、一件装入，货物变化按编号字典序排列。
			if len(res.CargoChanges) != 3 {
				t.Fatalf("应列出 3 条货物变化: %+v", res.CargoChanges)
			}
			wantChanges := []CargoChange{
				{CargoID: "G1", From: "C1", To: ""},
				{CargoID: "G2", From: "C1", To: ""},
				{CargoID: "G3", From: "", To: "C1"},
			}
			for i, want := range wantChanges {
				if res.CargoChanges[i] != want {
					t.Fatalf("第 %d 条货物变化错误: got=%+v want=%+v", i, res.CargoChanges[i], want)
				}
			}
			// C1 重量 50 -> 40。
			if len(res.CompartmentChanges) != 1 {
				t.Fatalf("应只列出 C1 的变化: %+v", res.CompartmentChanges)
			}
			cp := res.CompartmentChanges[0]
			if cp.CompartmentID != "C1" || cp.WeightBefore != 50 || cp.WeightAfter != 40 {
				t.Fatalf("C1 重量变化错误: %+v", cp)
			}
			// 查询：剩余 60，清单只含 G3。
			cpt, _ := r.Compartment("C1")
			if cpt.UsedWeight != 40 || cpt.RemainingWeight != 60 {
				t.Fatalf("C1 重量错误: %+v", cpt)
			}
			if len(cpt.Cargo) != 1 || cpt.Cargo[0].ID != "G3" {
				t.Fatalf("C1 清单应只含 G3: %+v", cpt.Cargo)
			}
			// 货物归属与舱位清单相互对应。
			g3, _ := r.Cargo("G3")
			if !g3.Loaded || g3.CompartmentID != "C1" {
				t.Fatalf("G3 应已装入 C1: %+v", g3)
			}
			for _, id := range []string{"G1", "G2"} {
				cv, _ := r.Cargo(id)
				if cv.Loaded || cv.CompartmentID != "" {
					t.Fatalf("%s 记录应保留且为未装载: %+v", id, cv)
				}
			}
			assertReplaceProfilesUnchanged(t, r, true)
		})
	}
}

// G3 登记为不允许混装时，最终舱位只有它一件货物，仍应允许装入
// （没有不同目的地货物共舱，混装许可无关）。
func TestReplaceWithNonMixedIncomingCargoSuccess(t *testing.T) {
	for _, tc := range []struct {
		name string
		ops  []Op
	}{
		{name: "先卸后装", ops: []Op{
			{Kind: OpUnload, CargoID: "G1"},
			{Kind: OpUnload, CargoID: "G2"},
			{Kind: OpLoad, CargoID: "G3", Target: "C1"},
		}},
		{name: "先装后卸", ops: []Op{
			{Kind: OpLoad, CargoID: "G3", Target: "C1"},
			{Kind: OpUnload, CargoID: "G1"},
			{Kind: OpUnload, CargoID: "G2"},
		}},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := newReplaceRegistry(t, false)
			res, err := r.Adjust("A1", tc.ops)
			if err != nil {
				t.Fatalf("最终只有不允许混装的 G3 一件时应允许装入: %v", err)
			}
			if res.ID != "A1" {
				t.Fatalf("结果编号错误: %+v", res)
			}
			cpt, _ := r.Compartment("C1")
			if cpt.UsedWeight != 40 || cpt.RemainingWeight != 60 || len(cpt.Cargo) != 1 {
				t.Fatalf("C1 最终配载错误: %+v", cpt)
			}
			if cpt.Cargo[0].ID != "G3" || cpt.Cargo[0].AllowMixed {
				t.Fatalf("C1 应只剩 G3 且保留其不允许混装登记: %+v", cpt.Cargo[0])
			}
			assertReplaceProfilesUnchanged(t, r, false)
		})
	}
}

// 只卸下 G1、装入允许混装的 G3：最终留下去上海且不允许混装的 G2，
// 与去北京的 G3 共舱。总重量 70 未超重，仍必须按混装冲突拒绝整次调整，
// 且不能因卸货操作排在前面就把 G1 单独卸下。先卸后装与先装后卸结论一致。
func TestPartialReplaceMixedConflictRejected(t *testing.T) {
	for _, tc := range []struct {
		name string
		ops  []Op
	}{
		{
			name: "先卸后装",
			ops: []Op{
				{Kind: OpUnload, CargoID: "G1"},
				{Kind: OpLoad, CargoID: "G3", Target: "C1"},
			},
		},
		{
			name: "先装后卸",
			ops: []Op{
				{Kind: OpLoad, CargoID: "G3", Target: "C1"},
				{Kind: OpUnload, CargoID: "G1"},
			},
		},
	} {
		t.Run(tc.name, func(t *testing.T) {
			r := newReplaceRegistry(t, true)
			res, err := r.Adjust("A1", tc.ops)
			if err == nil {
				t.Fatalf("留有不允许混装的 G2 时应拒绝整次调整，却返回成功: %+v", res)
			}
			if res != nil {
				t.Fatalf("被拒绝的调整不应返回成功结果: %+v", res)
			}
			se := requireError(t, err, ErrMixedLoading)
			// 结构化原因指出 G2 并携带此次调整编号。
			if se.ID != "G2" {
				t.Fatalf("混装冲突应指出不允许混装的 G2，实际 ID=%q", se.ID)
			}
			if se.AdjustmentID != "A1" {
				t.Fatalf("混装冲突应携带调整编号 A1，实际 AdjustmentID=%q", se.AdjustmentID)
			}
			// 说明中能看出涉及 C1。
			if !strings.Contains(se.Error(), "C1") {
				t.Fatalf("混装说明应指出舱位 C1: %s", se.Error())
			}
			// 拒绝后整次调整不生效：G1、G2 仍在 C1，G3 仍未装载。
			g1, _ := r.Cargo("G1")
			g2, _ := r.Cargo("G2")
			g3, _ := r.Cargo("G3")
			if g1.CompartmentID != "C1" || !g1.Loaded {
				t.Fatalf("G1 不应被单独卸下: %+v", g1)
			}
			if g2.CompartmentID != "C1" || !g2.Loaded {
				t.Fatalf("G2 应留在 C1: %+v", g2)
			}
			if g3.Loaded || g3.CompartmentID != "" {
				t.Fatalf("G3 应仍未装载: %+v", g3)
			}
			// 已用 50、剩余 50。
			cpt, _ := r.Compartment("C1")
			if cpt.UsedWeight != 50 || cpt.RemainingWeight != 50 {
				t.Fatalf("拒绝后舱位重量应保持 50/50: %+v", cpt)
			}
			if len(cpt.Cargo) != 2 || cpt.Cargo[0].ID != "G1" || cpt.Cargo[1].ID != "G2" {
				t.Fatalf("C1 清单应仍是 G1、G2: %+v", cpt.Cargo)
			}
			assertReplaceProfilesUnchanged(t, r, true)
		})
	}
}

// Package stowage 提供本地舱单与配载能力：
// 登记舱位与货物、执行多货物的装卸调整、预览调整结果、更正货物资料，
// 并可随时查询配载状态。
//
// 舱位以唯一编号和最大承重（正整数千克）标识；货物以唯一编号、
// 重量（正整数千克）、目的地及是否允许混装标识。货物登记后处于
// 未装载状态，可通过调整进行装载、卸下或移动。AmendCargo 可在货物
// 编号与所属舱位不变的前提下整体替换其重量、目的地与混装许可；已
// 装载货物按三项资料共同生效后的最终配载校验，更正不占用调整编号。
//
// 一次调整可包含多件货物的操作，全部操作按完成后的最终配载统一
// 校验：舱位总重量不得超过承重；不同目的地货物共舱时所有货物都
// 必须允许混装。任一操作不合法，整次调整不生效。
//
// Preview 在不改变任何状态的前提下预演同一批操作，给出能否提交、
// 涉及货物的原舱位与预计舱位、受影响舱位前后完整配载，以及全部
// 拒绝原因；正式提交仍以 Adjust 提交时的状态重新判断。
package stowage

// Ready 表示基线可以运行。
func Ready() bool { return true }

package stowage_test

import (
	"errors"
	"fmt"

	"github.com/descikazuyq/cargo-stowage/stowage"
)

// newSwapRegistry 新建登记处并完成初始配载：两个承重均为 30 千克的舱位，
// 各装入一件 30 千克、目的地相同且不允许混装的货物。每个示例都从这里
// 独立开始，不依赖其他示例留下的状态。
func newSwapRegistry() *stowage.Registry {
	reg := stowage.NewRegistry()
	must := func(err error) {
		if err != nil {
			panic(err)
		}
	}
	must(reg.RegisterCompartment("C1", 30))
	must(reg.RegisterCompartment("C2", 30))
	must(reg.RegisterCargo("G1", 30, "上海", false))
	must(reg.RegisterCargo("G2", 30, "上海", false))
	_, err := reg.Adjust("load-1", []stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G1", Target: "C1"},
		{Kind: stowage.OpLoad, CargoID: "G2", Target: "C2"},
	})
	must(err)
	return reg
}

// cargoIDs 提取舱位快照中的货物编号清单。
func cargoIDs(v stowage.CompartmentView) []string {
	ids := make([]string, 0, len(v.Cargo))
	for _, c := range v.Cargo {
		ids = append(ids, c.ID)
	}
	return ids
}

// 预览同一批安排中的两件货物互换：两个舱位各自满载，但限制按整批安排
// 完成后的最终配载判断，交换后每个舱位仍恰好在承重内，因此可以提交。
func Example_previewSwap() {
	reg := newSwapRegistry()

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpMove, CargoID: "G1", Target: "C2"},
		{Kind: stowage.OpMove, CargoID: "G2", Target: "C1"},
	})
	if err != nil {
		panic(err)
	}

	fmt.Println("可提交:", res.Submittable)
	for _, ch := range res.CargoChanges {
		fmt.Printf("货物 %s: %s -> %s\n", ch.CargoID, ch.From, ch.To)
	}
	// 即使交换后总重量不变，两个舱位仍会列出前后的完整货物清单。
	for _, cp := range res.Compartments {
		fmt.Printf("舱位 %s 前: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.Before), cp.Before.UsedWeight, cp.Before.MaxWeight)
		fmt.Printf("舱位 %s 后: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.After), cp.After.UsedWeight, cp.After.MaxWeight)
	}
	// 预计清单中的货物位置按交换后的所属舱位解释。
	fmt.Printf("预计清单中 %s 属于舱位 %s\n",
		res.Compartments[0].After.Cargo[0].ID,
		res.Compartments[0].After.Cargo[0].CompartmentID)

	// 预览是只读的：查询当前货物仍看到交换前的位置。
	g1, _ := reg.Cargo("G1")
	fmt.Println("预览后查询 G1 所在舱位:", g1.CompartmentID)

	// Output:
	// 可提交: true
	// 货物 G1: C1 -> C2
	// 货物 G2: C2 -> C1
	// 舱位 C1 前: [G1]（30/30 千克）
	// 舱位 C1 后: [G2]（30/30 千克）
	// 舱位 C2 前: [G2]（30/30 千克）
	// 舱位 C2 后: [G1]（30/30 千克）
	// 预计清单中 G2 属于舱位 C1
	// 预览后查询 G1 所在舱位: C1
}

// 预览一组会被拒绝的安排：向已满载的 C1 装入第三件货物（10 千克、目的地
// 不同、允许混装）。每条操作本身合法，预览照常返回预计清单，但
// Submittable 为 false，且同时列出超重与混装冲突两条拒绝原因。
func Example_previewRejected() {
	reg := newSwapRegistry()
	if err := reg.RegisterCargo("G3", 10, "北京", true); err != nil {
		panic(err)
	}

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G3", Target: "C1"},
	})
	// 操作本身合法，预览调用不失败；不可提交体现在结果里。
	fmt.Println("预览调用出错:", err != nil)
	fmt.Println("可提交:", res.Submittable)
	for _, cp := range res.Compartments {
		fmt.Printf("舱位 %s 后: %v（%d/%d 千克）\n",
			cp.ID, cargoIDs(cp.After), cp.After.UsedWeight, cp.After.MaxWeight)
	}
	for _, rej := range res.Rejections {
		switch rej.Kind {
		case stowage.ErrOverweight:
			fmt.Printf("舱位 %s 超重 %d 千克（%d/%d）\n",
				rej.CompartmentID, rej.Overweight, rej.UsedWeight, rej.MaxWeight)
		case stowage.ErrMixedLoading:
			for _, d := range rej.Destinations {
				fmt.Printf("舱位 %s 目的地 %s: %v\n", rej.CompartmentID, d.Destination, d.CargoIDs)
			}
			fmt.Printf("不允许混装的货物: %v\n", rej.OffendingCargo)
		}
	}

	// 被拒绝的预览同样不改变配载。
	c1, _ := reg.Compartment("C1")
	fmt.Println("预览后 C1 实际货物:", cargoIDs(*c1))

	// Output:
	// 预览调用出错: false
	// 可提交: false
	// 舱位 C1 后: [G1 G3]（40/30 千克）
	// 舱位 C1 超重 10 千克（40/30）
	// 舱位 C1 目的地 上海: [G1]
	// 舱位 C1 目的地 北京: [G3]
	// 不允许混装的货物: [G1]
	// 预览后 C1 实际货物: [G1]
}

// 操作本身不合法（货物编号不存在）时，预览返回结构化错误且没有局部
// 预览，与“操作合法但最终配载不可提交”的拒绝结果不同。
func Example_previewInvalidOp() {
	reg := newSwapRegistry()

	res, err := reg.Preview([]stowage.Op{
		{Kind: stowage.OpLoad, CargoID: "G9", Target: "C1"},
	})
	fmt.Println("有预览结果:", res != nil)
	var serr *stowage.Error
	if errors.As(err, &serr) {
		fmt.Println("错误原因:", serr.Kind)
		fmt.Println("涉及编号:", serr.ID)
	}

	// Output:
	// 有预览结果: false
	// 错误原因: 对象不存在
	// 涉及编号: G9
}

// 预览通过后用同一批操作正式提交：只有 Adjust 成功才应用安排，此后的
// 查询结果与之前的预计配载对应。
func Example_adjustAfterPreview() {
	reg := newSwapRegistry()

	ops := []stowage.Op{
		{Kind: stowage.OpMove, CargoID: "G1", Target: "C2"},
		{Kind: stowage.OpMove, CargoID: "G2", Target: "C1"},
	}
	res, err := reg.Preview(ops)
	if err != nil {
		panic(err)
	}
	fmt.Println("预览可提交:", res.Submittable)

	// 预览本身不改变配载，也不占用调整编号；正式提交才应用安排。
	adj, err := reg.Adjust("swap-1", ops)
	if err != nil {
		panic(err)
	}
	fmt.Println("已提交调整:", adj.ID)
	g1, _ := reg.Cargo("G1")
	g2, _ := reg.Cargo("G2")
	fmt.Println("提交后 G1 所在舱位:", g1.CompartmentID)
	fmt.Println("提交后 G2 所在舱位:", g2.CompartmentID)

	// Output:
	// 预览可提交: true
	// 已提交调整: swap-1
	// 提交后 G1 所在舱位: C2
	// 提交后 G2 所在舱位: C1
}

